/**
 * Retrospective of a pipeline run (annex B section B.20, owner 106; F106-FR-034, F106-FR-035) — the record type of schema id `specstride.retrospective/1`.
 *
 * Generated by `scripts/types.mjs` from `schemas/retrospective-106.schema.json` (research.md,
 * D-1) — do not edit; re-run the `build` script of the package instead. The
 * fields keep the meaning, the type in words and the required cell of the
 * annex as documentation.
 */
export interface Retrospective106 {
  schema: unknown;
  /**
   * Id of the pipeline the retrospective is about
   */
  pipeline?: string;
  /**
   * The launch contract hash the retrospective was computed against; the retrospective is filed under it (field name as at the baseline)
   */
  contract_digest?: string;
  /**
   * Local time with offset, to the second, as at the baseline
   */
  generated_at?: string;
  stages?: Array<{
    stage: string;
    status: "ok" | "unavailable";
    /**
     * Present when the status is unavailable; passed through the one ingress (F106-FR-040)
     */
    reason?: string;
    /**
     * Working directory of the located feature
     */
    workdir?: string;
    /**
     * Directory of the located feature
     */
    feature_dir?: string;
    /**
     * Slug of the located feature
     */
    feature?: string;
    /**
     * Schema id of the summary that learn --summarize returned
     */
    summary_schema?: string | null;
    /**
     * The totals of that summary, copied
     */
    totals?: unknown;
    /**
     * Per phase: title, attempts_total, attempts_to_approval, cost_usd, work_sec_p50, work_sec_p90, work_sec_samples, copied from the summary
     */
    phases?: Record<string, unknown>;
    /**
     * The evaluation lines, as the learn command reports them; passed through the one ingress (F106-FR-040)
     */
    evaluations?: Array<string>;
    /**
     * The suggestion lines; a suggestion is never run
     */
    suggestions?: Array<string>;
  }>;
}
